/**
 * The site-kit contract: forms and third-party scripts.
 *
 * These are the shapes of files that live in the *site's* repository — a form
 * is one JSON file, the scripts setup is one JSON file — so that they are
 * edited like any other content (by hand, in the app's builders, by the
 * assistant, over MCP), proofed, and published. The site renders them with a
 * small runtime (`@galley/astro` for Astro sites); the app edits them with
 * dedicated screens. Types only — no runtime code — so the site runtime, the
 * web UI and the engine can all import this file.
 */
/** Any value JSON can hold. (Mirrors JsonValue in @galley/core/types.) */
export type JsonPrimitive = string | number | boolean | null;
export type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };

// ─────────────────────────────────────────────────────────────── forms

export type FormFieldType =
  | "text"
  | "email"
  | "tel"
  | "url"
  | "number"
  | "textarea"
  | "select"
  | "radio"
  | "checkbox" // one yes/no box
  | "checkboxes" // several choices
  | "date"
  | "hidden"
  | "consent" // a required-or-not agreement with its own text
  | "heading" // layout only: a sub-heading inside the form
  | "paragraph"; // layout only: a line of explanatory text

export interface FormFieldOption {
  value: string;
  label: string;
}

/** Where a hidden (or prefilled) field takes its value from on the page. */
export interface FormAutofill {
  /**
   * "query": a query-string parameter (`key`); "utm": the UTM parameter `key`,
   * remembered from the visitor's first and latest landing; "referrer";
   * "page-url"; "page-title"; "cookie": a first-party cookie (`key`).
   */
  from: "query" | "utm" | "referrer" | "page-url" | "page-title" | "cookie";
  key?: string;
  /** For "utm": which landing to report. Default "last". */
  touch?: "first" | "last";
}

export interface FormField {
  /** Stable id within the form (lowercase, hyphens/underscores). */
  id: string;
  type: FormFieldType;
  label?: string;
  /** Name sent to a destination when its mapping has no entry. Default: `id`. */
  name?: string;
  placeholder?: string;
  /** A line of help under the field. */
  help?: string;
  required?: boolean;
  /** select / radio / checkboxes. */
  options?: FormFieldOption[];
  defaultValue?: string;
  /** Two "half" fields sit side by side on wide screens. Default "full". */
  width?: "full" | "half";
  validation?: {
    /** A regular expression the value must match. */
    pattern?: string;
    minLength?: number;
    maxLength?: number;
    min?: number;
    max?: number;
    /** Shown when the value is refused. */
    message?: string;
    /** email: refuse free mailbox providers (gmail.com, outlook.com, …). */
    businessEmailOnly?: boolean;
  };
  /** Show (and submit) this field only when another field has a given value. */
  showWhen?: { field: string; equals?: string; notEquals?: string; in?: string[] };
  autofill?: FormAutofill;
  /** consent / paragraph / heading: the text itself (inline markdown allowed). */
  text?: string;
  /** Which step it belongs to in a multi-step form (0-based). Default 0. */
  step?: number;
}

/**
 * Where submissions go. Built-in providers:
 *   "galley"      — the Galley capture endpoint (the default; settings: { endpoint? })
 *   "hubspot"     — HubSpot Forms API (settings: { portalId, formId, region? })
 *   "marketo"     — Marketo Forms 2.0 (settings: { munchkinId, formId, host })
 *   "salesforce"  — Salesforce Web-to-Lead (settings: { orgId, returnUrl?, mode?: "frame" | "navigate" })
 *   "pardot"      — Account Engagement form handler (settings: { handlerUrl, successLocation?, errorLocation?, mode?: "frame" | "navigate" })
 *   "webhook"     — any endpoint that accepts a POST (settings: { url, format?: "json" | "form" })
 *   "mailto"      — the visitor's own mail program (settings: { to, subject? }) — last resort
 * Plugins may add more.
 */
export type FormProviderId =
  | "galley"
  | "hubspot"
  | "marketo"
  | "salesforce"
  | "pardot"
  | "webhook"
  | "mailto"
  | (string & {});

export interface FormDestination {
  provider: FormProviderId;
  settings: { [key: string]: JsonValue };
  /** Form field id → the provider's field name. Unmapped fields use `name ?? id`. */
  mapping?: { [fieldId: string]: string };
  /** Extra fixed values sent with every submission (campaign ids, lead source). */
  constants?: { [providerField: string]: string };
  /** Send to this destination only when a field has a given value. */
  when?: { field: string; equals: string };
}

/** What happens after a successful submission. Run in order. */
export type FormAction =
  /** Replace the form with a thank-you (inline markdown; `{{field}}` placeholders). */
  | { type: "message"; title?: string; text: string }
  /** Go to another page. `passFields` are appended as query parameters. */
  | { type: "redirect"; url: string; passFields?: string[]; delaySeconds?: number }
  /** Offer (or start) a download. */
  | { type: "download"; url: string; label?: string; auto?: boolean }
  /** Record a conversion: pushed to `dataLayer` / `gtag` / a DOM CustomEvent. */
  | { type: "event"; name: string; target?: "dataLayer" | "gtag" | "dom"; params?: { [key: string]: string } }
  /** An extra POST of the submission, not awaited (a chat alert, a spreadsheet). */
  | { type: "webhook"; url: string }
  /** Custom JavaScript, called with the submitted values. Build mode only. */
  | { type: "script"; code: string };

export interface FormDefinition {
  /** Shown in the app and to screen readers as the form's name. */
  name: string;
  description?: string;
  fields: FormField[];
  submitLabel: string;
  /** Titles for a multi-step form; absent or one entry = a single step. */
  steps?: Array<{ title?: string; nextLabel?: string }>;
  /** Every destination receives the submission; the first decides success. */
  destinations: FormDestination[];
  afterSubmit: FormAction[];
  /** Shown when the submission could not be sent. */
  errorMessage?: string;
  /**
   * Replaces the runtime's default wording for this form, by key: "required",
   * "email", "businessEmail", "summary", "sending", "next", "back", "step",
   * "tooFast", "rateLimited", "noScript", "thanksTitle", "thanksText" … (the
   * site runtime documents the full list and the `{placeholders}` each takes).
   */
  messages?: { [key: string]: string };
  spam?: {
    /** A hidden field bots fill in. Default true. */
    honeypot?: boolean;
    /** Refuse submissions made faster than this after the form appeared. */
    minSeconds?: number;
    /** Cloudflare Turnstile site key, when the destination verifies it. */
    turnstileSiteKey?: string;
  };
  appearance?: {
    layout?: "stacked" | "inline";
    size?: "regular" | "compact";
    /** Where labels sit. */
    labels?: "above" | "floating" | "hidden";
  };
}

/** One submission as the Galley capture endpoint stores it. */
export interface FormSubmission {
  id: string;
  siteId: string;
  /** The form's id (its file name without extension). */
  form: string;
  /** ISO 8601. */
  at: string;
  values: { [fieldId: string]: string | string[] };
  /** Page it was sent from, and how the visitor arrived. */
  page?: { url?: string; title?: string; referrer?: string };
  /** Per-destination forwarding results (for forms that also forward). */
  delivery?: Array<{
    provider: string;
    ok: boolean;
    detail?: string;
    /** Index into the form's `destinations`; absent for the e-mail notification (`provider: "email"`). */
    destination?: number;
    /** How many tries the last result took. */
    attempts?: number;
    /** ISO 8601 time of the last try. */
    at?: string;
  }>;
  /** Marked by the spam checks; kept but hidden by default. */
  spam?: boolean;
  /** Which spam check marked it: "honeypot", "too-fast", "turnstile". */
  spamReason?: string;
  read?: boolean;
  /** Sent with "Send a test submission" from the app. */
  test?: boolean;
}

// ─────────────────────────────────────────────────────────────── scripts

/** What a visitor must have agreed to before a script may load. */
export type ConsentCategory = "necessary" | "analytics" | "marketing" | "preferences";

/**
 * One third-party script. `kind` names a known integration whose snippet the
 * runtime writes correctly from a few settings — "gtm" ({ containerId }),
 * "ga4" ({ measurementId }), "meta-pixel" ({ pixelId }), "linkedin-insight"
 * ({ partnerId }), "hubspot" ({ portalId }), "marketo-munchkin"
 * ({ munchkinId }), "plausible" ({ domain }), "segment" ({ writeKey }),
 * "hotjar" ({ siteId }), "clarity" ({ projectId }), "intercom" ({ appId }) —
 * or "custom" ({ src?, inline?, attributes? }). Plugins may add kinds.
 */
export interface ScriptEntry {
  id: string;
  kind: string;
  /** Shown in the app. Default: the integration's name. */
  label?: string;
  enabled: boolean;
  settings: { [key: string]: JsonValue };
  placement?: "head" | "body-start" | "body-end";
  /**
   * "eager": in the page's initial HTML. "idle": once the page is idle.
   * "interaction": on the visitor's first scroll, tap or key press.
   */
  load?: "eager" | "idle" | "interaction";
  /** Absent = "necessary" for nothing known; integrations declare a default. */
  consent?: ConsentCategory;
  /** Page-path globs. Empty or absent `include` = every page. */
  include?: string[];
  exclude?: string[];
  /** Load in development and in the editor's preview too. Default false. */
  inPreview?: boolean;
  /** A note for colleagues: who asked for it and why. */
  note?: string;
}

export interface ConsentSettings {
  /**
   * "none": everything enabled loads. "banner": the built-in consent banner
   * asks first. "external": another consent tool decides and signals through
   * `window.galleyConsent.set(...)` or Google Consent Mode.
   */
  mode: "none" | "banner" | "external";
  /** Categories on before the visitor chooses. "necessary" is always on. */
  defaults?: ConsentCategory[];
  banner?: {
    title?: string;
    text?: string;
    acceptLabel?: string;
    rejectLabel?: string;
    settingsLabel?: string;
    /** The button that saves the choices made under "settings". */
    saveLabel?: string;
    policyUrl?: string;
    policyLabel?: string;
    /** Name and one-line description of each category, as the banner lists them. */
    categories?: { [category in ConsentCategory]?: { label?: string; description?: string } };
  };
  /** Send Google Consent Mode v2 signals to gtag/GTM. */
  googleConsentMode?: boolean;
}

export interface ScriptsConfig {
  scripts: ScriptEntry[];
  consent?: ConsentSettings;
}

/** What a known integration needs, for the app's "add a script" catalogue. */
export interface ScriptIntegrationInfo {
  kind: string;
  name: string;
  description: string;
  category: "tag-manager" | "analytics" | "advertising" | "marketing" | "support" | "other";
  defaultConsent: ConsentCategory;
  defaultPlacement: "head" | "body-start" | "body-end";
  /** The settings it asks for. */
  settings: Array<{ key: string; label: string; placeholder?: string; pattern?: string; help?: string; required?: boolean }>;
  docsUrl?: string;
}

/** What a form provider needs, for the app's destination picker. */
export interface FormProviderInfo {
  id: string;
  name: string;
  description: string;
  settings: Array<{ key: string; label: string; placeholder?: string; pattern?: string; help?: string; required?: boolean }>;
  /** Whether its field list can be read from an existing form on the provider's side. */
  canImportFields: boolean;
  docsUrl?: string;
}
